const app=document.querySelector("#app"),toast=document.querySelector("#toast");
const state={analysis:null,overview:null,detections:[],analyses:[]};
const esc=v=>{const n=document.createElement("span");n.textContent=v??"";return n.innerHTML};
const api=async(url,options={})=>{const r=await fetch(url,options),d=await r.json();if(!r.ok)throw Error(d.detail||"Request failed");return d};
const route=()=>location.hash.replace("#/","").split("?")[0]||"home";
const notify=(m,t="ok")=>{toast.textContent=m;toast.className="show "+t;setTimeout(()=>toast.className="",3500)};
const page=(title,kicker,body)=>`<section class="app-page"><div class="page-head"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1></div></div>${body}</section>`;
const empty=t=>`<div class="empty"><span>◎</span><h3>No evidence analysis yet</h3><p>${t}</p><a class="button" href="#/upload">Analyze evidence</a></div>`;
function datasetPicker(){return state.analyses.length?`<label class="dataset-picker">Dataset<select id="datasetSelect">${state.analyses.map(a=>`<option value="${a.id}" ${state.analysis?.id===a.id?"selected":""}>${esc(a.filename)} · ${a.event_count} rows</option>`).join("")}</select></label>`:""}
async function load(id){state.analyses=await api("/api/analyses");const chosen=id||state.analyses[0]?.id;if(chosen){state.analysis=await api("/api/analyses/"+chosen);state.overview=await api("/api/overview");state.detections=(await api("/api/detections?analysis_id="+chosen)).findings}else{state.analysis=null;state.detections=[];state.overview=await api("/api/overview")}}
function landing(){return `<section class="hero"><div class="hero-copy"><p class="eyebrow">ADVANCED NUCLEAR SECURITY PLATFORM</p><h1>Unified assurance for nuclear digital infrastructure</h1><p class="lede">A defensive read only platform connecting passive SCADA monitoring, safety system integrity, nuclear material safeguards, explainable threat detection and regulatory evidence for civil and defense applications.</p><div class="hero-actions"><a class="button" href="#/upload">Analyze evidence</a><a class="text-link" href="#/dashboard">Open assurance overview ↗</a></div><div class="principle"><span>Safety authority</span><strong>Technology prioritizes the evidence. Qualified people authorize every response.</strong></div></div><div class="plant-wrap"><div class="orbit"></div><img src="/assets/floating-plant.png" alt="Original fictional floating nuclear facility"><div class="float-label one"><b>ONE WAY</b><span>Evidence transfer</span></div><div class="float-label two"><b>PASSIVE</b><span>Read only analysis</span></div></div></section>
<section class="feature-band refined"><a href="#/scada"><b>01</b><span>SCADA protection<small>Passive OT evidence, baselines, assets and control-network anomalies.</small></span></a><a href="#/integrity"><b>02</b><span>Safety integrity<small>Firmware, logic and configuration assurance against approved state.</small></span></a><a href="#/safeguards"><b>03</b><span>Material safeguards<small>PACS, MC&amp;A and radiation evidence correlation.</small></span></a><a href="#/ai"><b>04</b><span>AI threat detection<small>Cross-domain correlation, explainability and evidence-linked alerts.</small></span></a><a href="#/devsecops"><b>05</b><span>DevSecOps<small>Controlled changes, integrity gates, approvals and recovery evidence.</small></span></a></section>
<section class="landing-command"><div class="landing-command-copy"><p class="eyebrow">EVIDENCE ASSURANCE LIFECYCLE</p><h2>Fresh analysis in the workspace. History stays controlled in Reports.</h2><p>NuclearShield starts each operational view from the newest completed evidence run. It preserves provenance, separates nuclear assurance domains, explains why findings triggered and keeps older analyses in a dedicated report history with deletion controls.</p><div class="landing-stats"><span><b>5</b>specialized assurance domains</span><span><b>2</b>passive network sensor formats</span><span><b>0</b>plant-control commands</span></div></div><div class="lifecycle"><a href="#/upload"><b>01</b><div><strong>Ingest & preserve</strong><span>Normalize CSV/JSON, expose rejected rows and bind the run to SHA-256 provenance.</span></div></a><a href="#/ai"><b>02</b><div><strong>Detect & correlate</strong><span>Apply baseline, integrity, authorization, robust anomaly and cross-domain correlation logic.</span></div></a><a href="#/monitoring"><b>03</b><div><strong>Observe & explain</strong><span>Review telemetry, Zeek/Suricata evidence, charts, confidence and alert reasons.</span></div></a><a href="#/reports"><b>04</b><div><strong>Report & audit</strong><span>Generate HTML assurance reports while preserving prior analyses and attributable audit evidence.</span></div></a></div></section>
<section class="landing-proof"><div><p class="eyebrow">WHAT THE PLATFORM PROVIDES</p><h2>Different evidence. Different assurance logic. One defensible review path.</h2></div><div class="proof-grid"><article><span>SCADA</span><strong>Passive OT visibility</strong><p>Assets, communication evidence, deviations and network findings without control exposure.</p></article><article><span>INTEGRITY</span><strong>Approved-state assurance</strong><p>Logic, firmware and configuration evidence checked against authorization and integrity state.</p></article><article><span>SAFEGUARDS</span><strong>Physical-cyber correlation</strong><p>Access, material-accounting and radiation evidence connected through actor and asset context.</p></article><article><span>AI DETECTION</span><strong>Explainable threat triage</strong><p>Statistical anomalies and correlations become confidence-scored, human-gated alerts.</p></article><article><span>MONITORING</span><strong>Operational observability</strong><p>Zeek/Suricata evidence plus Prometheus and Grafana application telemetry.</p></article><article><span>GOVERNANCE</span><strong>Traceable evidence</strong><p>Reports, compliance mappings, change assurance and persistent audit history.</p></article></div></section>
<section class="trust-architecture">
  <div class="trust-intro">
    <p class="eyebrow">TRUST ARCHITECTURE</p>
    <h2>From evidence to a defensible human decision.</h2>
    <p>Every NuclearShield workflow keeps provenance, detection logic and human authority visible without crossing the read only operational boundary.</p>
  </div>
  <div class="trust-path">
    <div><b>01</b><span>Evidence</span><small>Source bound and SHA 256 traceable</small></div>
    <i>→</i>
    <div><b>02</b><span>Analysis</span><small>Domain specific checks and correlation</small></div>
    <i>→</i>
    <div><b>03</b><span>Explanation</span><small>Reason, confidence and linked evidence</small></div>
    <i>→</i>
    <div><b>04</b><span>Human review</span><small>Qualified authority decides the response</small></div>
  </div>
  <div class="trust-boundary"><span>READ ONLY BOUNDARY</span><strong>Observe · verify · explain · report</strong><em>No plant control commands</em></div>
</section>`}
function upload(){return page("Analyze evidence","NORMALIZE · VALIDATE · DETECT · CORRELATE",`<div class="upload-layout"><form id="uploadForm" class="upload-card"><label id="dropzone" class="drop" for="evidence"><span class="drop-icon">＋</span><strong>Drop CSV, JSON, Suricata EVE or Zeek evidence</strong><small>Flexible column names · maximum 10 MB · up to 50,000 rows</small><input id="evidence" type="file" accept=".csv,.json,.jsonl,.ndjson,.log" required></label><div id="fileName" class="file-name">No file selected</div><button class="button">Run complete analysis</button><button id="demo" class="button ghost" type="button">Analyze 24-row synthetic demonstration</button><p id="uploadStatus">Every accepted row is normalized, hashed, scored and persisted.</p></form><aside class="schema"><h2>Analysis engines</h2>${[["Schema adapter","Infers common ID, time, source, value and event-class fields."],["Baseline engine","Compares numeric and categorical observations."],["Integrity engine","Checks declared hashes, signatures and approved states."],["AI-assisted model","Median/MAD robust anomaly scoring for groups with 5+ numeric rows."],["Correlation engine","Links unauthorized access with asset or actor activity."],["Governance gate","No automatic containment; human authorization is mandatory."]].map(x=>`<div class="schema-row"><b>${x[0]}</b><span>${x[1]}</span></div>`).join("")}</aside></div>`)}
const bar=(l,v,total,c="teal")=>`<div class="bar-row"><div><span>${esc(l)}</span><b>${v}</b></div><i><em class="${c}" style="width:${total?Math.max(2,Math.round(v/total*100)):0}%"></em></i></div>`;
const palette=["#2878b8","#19a6a2","#6f63c2","#d29a32","#d65a63","#4d9c68"];
function donut(title,items){const vals=items.map(x=>Math.max(0,Number(x[1])||0)),total=vals.reduce((a,b)=>a+b,0)||1;let a=0;const stops=vals.map((v,i)=>{const st=a;a+=v/total*100;return `${palette[i%palette.length]} ${st}% ${a}%`}).join(",");return `<article class="viz-card"><div class="panel-head"><h2>${title}</h2><span>${vals.reduce((x,y)=>x+y,0)} total</span></div><div class="donut-wrap"><div class="donut" style="background:conic-gradient(${stops||'#dfe9ed 0 100%'})"><b>${vals.reduce((x,y)=>x+y,0)}</b><small>events</small></div><div class="legend">${items.map((x,i)=>`<span><i style="background:${palette[i%palette.length]}"></i>${esc(x[0])}<b>${x[1]}</b></span>`).join("")}</div></div></article>`}
function spark(title,values,label="evidence trend"){const a=(values||[]).map(Number).filter(Number.isFinite);if(!a.length)a.push(0);const max=Math.max(...a,1),min=Math.min(...a,0),range=max-min||1,w=520,h=150,pad=12,pts=a.map((v,i)=>`${pad+(i*(w-pad*2)/Math.max(1,a.length-1))},${h-pad-((v-min)/range)*(h-pad*2)}`).join(' ');return `<article class="viz-card"><div class="panel-head"><h2>${title}</h2><span>${label}</span></div><svg class="spark" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(title)}"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#2589c9" stop-opacity=".28"/><stop offset="1" stop-color="#2589c9" stop-opacity=".02"/></linearGradient></defs><polyline class="gridline" points="12,40 508,40"/><polyline class="gridline" points="12,80 508,80"/><polyline class="gridline" points="12,120 508,120"/><polygon fill="url(#area)" points="${pad},${h-pad} ${pts} ${w-pad},${h-pad}"/><polyline class="sparkline" points="${pts}"/></svg><div class="viz-foot"><span>min <b>${min}</b></span><span>max <b>${max}</b></span><span>samples <b>${a.length}</b></span></div></article>`}
function values(rows){return rows.map(e=>Number(e.value)).filter(Number.isFinite)}
function domainStats(types){const rows=(state.analysis?.events||[]).filter(e=>types.includes(e.event_type)),fs=(state.detections||[]).filter(f=>types.includes(f.event?.event_type));return {rows,fs,critical:fs.filter(f=>f.severity==="critical").length,high:fs.filter(f=>f.severity==="high").length,medium:fs.filter(f=>f.severity==="medium").length,low:fs.filter(f=>f.severity==="low").length}}
function alertsOrClear(fs,title="Priority alerts"){const a=fs.filter(f=>["critical","high","medium"].includes(f.severity)).slice(0,8);return `<section class="alert-zone"><div class="panel-head"><h2>${title}</h2><span>${a.length?a.length+" active":"No priority alerts"}</span></div>${a.length?alertCards(a):`<div class="clear-state"><b>✓ No priority alert generated</b><span>The latest evidence did not meet the configured priority threshold.</span></div>`}</section>`}
function queue(list=state.detections){return `<div class="panel table-panel"><div class="panel-head"><h2>Detection queue</h2><span>${list.length} findings</span></div><div class="table-wrap"><table><thead><tr><th>Severity</th><th>Event</th><th>Detection</th><th>Engine</th><th>Confidence</th><th></th></tr></thead><tbody>${list.map(f=>`<tr><td><span class="tag ${f.severity}">${f.severity}</span></td><td><b>${esc(f.event_id)}</b><small>${esc(f.event.timestamp)}</small></td><td>${esc(f.detected)}</td><td><code>${esc(f.engine)}</code></td><td><strong>${f.confidence}%</strong></td><td><button class="row-link" data-event="${esc(f.event_id)}">Inspect</button></td></tr>`).join("")||'<tr><td colspan="6">No findings match this view.</td></tr>'}</tbody></table></div></div>`}
function dashboard(){if(!state.analysis)return page("Command center","LIVE FROM THE SELECTED DATASET",empty("Upload one or more evidence files to populate the platform."));const s=state.analysis.summary||{},sev=s.severities||{};return page("Command center","LIVE FROM THE SELECTED DATASET",`<div class="analysis-banner"><div><span>ACTIVE DATASET</span><strong>${esc(state.analysis.filename)}</strong><small>SHA-256 ${state.analysis.digest}</small></div><a href="/api/report?analysis_id=${state.analysis.id}" target="_blank">Open full report ↗</a></div><div class="metric-grid"><article><span>Rows processed</span><strong>${s.accepted_records||0}</strong><small>${s.processing_coverage||0}% processing coverage</small></article><article><span>Findings</span><strong>${state.analysis.finding_count}</strong><small>${s.finding_rate||0}% of accepted records</small></article><article><span>Critical / high</span><strong class="critical-text">${(sev.critical||0)+(sev.high||0)}</strong><small>Qualified review required</small></article><article><span>Rejected rows</span><strong>${s.rejected_records||0}</strong><small>Visible, never silently dropped</small></article></div><div class="dashboard-grid"><article class="panel"><div class="panel-head"><h2>Finding severity</h2></div>${["critical","high","medium","low"].map((x,i)=>bar(x,sev[x]||0,state.analysis.finding_count,["red","amber","teal","teal"][i])).join("")}</article><article class="panel"><div class="panel-head"><h2>Evidence processed by domain</h2></div>${Object.entries(s.evidence_types||{}).map(([k,v])=>bar(k,v,s.accepted_records)).join("")}</article></div>${queue(state.detections.slice(0,6))}`)}
function detections(kind=null){if(!state.analysis)return page("Detections","EXPLAINABLE REVIEW QUEUE",empty("Analyze evidence to generate findings."));const list=kind?state.detections.filter(f=>f.event.event_type===kind):state.detections;return page(kind==="integrity"?"Safety-system integrity":"Detections","FILTERED · EVIDENCE-LINKED · HUMAN-GATED",`<div class="filterbar"><input id="search" placeholder="Search event, source, reason"><select id="typeFilter"><option value="">All evidence types</option>${["network","integrity","access","material","radiation","change"].map(x=>`<option ${x===kind?"selected":""}>${x}</option>`).join("")}</select><select id="severityFilter"><option value="">All severities</option><option>critical</option><option>high</option><option>medium</option><option>low</option></select></div><div id="queue">${queue(list)}</div>`)}
function evidence(){if(!state.analysis)return page("Evidence explorer","ALL ACCEPTED RECORDS",empty("Upload evidence to inspect normalized records."));const rows=state.analysis.events;return page("Evidence explorer","NORMALIZED RECORDS FROM THE SELECTED FILE",`<div class="metric-grid"><article><span>Accepted</span><strong>${rows.length}</strong></article><article><span>Rejected</span><strong>${state.analysis.rejected?.length||0}</strong></article><article><span>Coverage</span><strong>${state.analysis.summary.processing_coverage}%</strong></article><article><span>File digest</span><strong>${state.analysis.digest.slice(0,8)}</strong></article></div><div class="table-wrap panel"><table><thead><tr><th>Event</th><th>Time</th><th>Domain</th><th>Source / asset</th><th>Observed</th><th>Baseline</th></tr></thead><tbody>${rows.map(e=>`<tr><td><b>${esc(e.event_id)}</b><small>row ${e.raw_row}</small></td><td>${esc(e.timestamp)}</td><td><span class="tag">${esc(e.event_type)}</span></td><td>${esc(e.source)}<small>${esc(e.asset)}</small></td><td>${esc(e.value)}</td><td>${esc(e.baseline)}</td></tr>`).join("")}</tbody></table></div>`)}
function scada(){if(!state.analysis)return page("Nuclear SCADA protection","PASSIVE OT EVIDENCE · DEFENSE IN DEPTH",empty("Analyze evidence to activate the SCADA protection view."));const rows=state.analysis.events.filter(e=>e.event_type==="network"),fs=state.detections.filter(f=>f.event.event_type==="network"),assets=[...new Set(rows.map(e=>e.asset).filter(Boolean))],sources=[...new Set(rows.map(e=>e.source).filter(Boolean))],crit=fs.filter(f=>["critical","high"].includes(f.severity)).length,sourceMix=sources.slice(0,6).map(x=>[x,rows.filter(r=>r.source===x).length]);return page("Nuclear SCADA protection","PASSIVE NETWORK VISIBILITY · ASSET EXPOSURE · BASELINE DEVIATION",`<div class="metric-grid scada-metrics"><article><span>Passive records</span><strong>${rows.length}</strong><small>network evidence</small></article><article><span>OT assets</span><strong>${assets.length}</strong><small>observed inventory</small></article><article><span>Sources</span><strong>${sources.length}</strong><small>passive collectors</small></article><article><span>Priority anomalies</span><strong>${crit}</strong><small>critical + high</small></article></div><div class="domain-viz scada-viz"><article class="viz-card wide">${spark("SCADA signal deviation",values(rows),"passive sequence")}</article><article class="viz-card"><div class="panel-head"><h2>Source distribution</h2><span>evidence mix</span></div>${sourceMix.map(x=>bar(x[0],x[1],Math.max(1,rows.length),"teal")).join("")||'<div class="rail-clear">No source labels observed.</div>'}</article></div>${alertRail(fs,"SCADA anomaly alerts")}<div class="panel asset-matrix"><div class="panel-head"><h2>Observed OT asset matrix</h2><span>read only</span></div><div class="asset-chips">${assets.map(a=>`<span><b>${esc(a)}</b><small>${rows.filter(r=>r.asset===a).length} observations</small></span>`).join("")||'<span><b>Unidentified</b><small>No named assets in evidence</small></span>'}</div></div>${queue(fs)}`)}
function ai(){if(!state.analysis)return page("AI-driven nuclear threat detection","ANOMALIES · CORRELATION · THREAT ALERTS",empty("Analyze evidence to activate threat detection."));const fs=state.detections,su=state.analysis.summary||{},types=["network","integrity","access","material","radiation","change"],correlated=fs.filter(f=>f.related_events?.length),aiFindings=fs.filter(f=>String(f.engine).includes("robust")||String(f.engine).includes("correlation")),sev=["critical","high","medium","low"].map(k=>[k,fs.filter(f=>f.severity===k).length]);return page("AI-driven threat detection","DETECT · CORRELATE · EXPLAIN · ALERT · AUTHORIZE",`<div class="notice"><b>Safety boundary:</b> Threat detection prioritizes uploaded evidence and generates review alerts. It cannot execute containment or modify a plant system.</div><div class="metric-grid accent-metrics"><article><span>Total findings</span><strong>${fs.length}</strong><small>across evidence domains</small></article><article><span>AI / correlation</span><strong>${aiFindings.length}</strong><small>robust + correlation engines</small></article><article><span>Cross-domain links</span><strong>${correlated.length}</strong><small>related actor/asset evidence</small></article><article><span>Critical / high</span><strong>${fs.filter(f=>["critical","high"].includes(f.severity)).length}</strong><small>priority human review</small></article></div><div class="viz-grid">${donut("Threat severity",sev)}${donut("Threats by domain",types.map(t=>[t,fs.filter(f=>f.event.event_type===t).length]))}</div>${alertRail(fs,"Generated threat alerts")}<div class="dashboard-grid"><article class="panel"><div class="panel-head"><h2>Detection engine activity</h2><span>${Object.keys(su.engines||{}).length} engines</span></div>${Object.entries(su.engines||{}).map(([k,v])=>bar(k,v,Math.max(1,fs.length))).join("")||'<div class="clear-state"><b>No engine findings</b><span>No detection engine produced a finding in this run.</span></div>'}</article><article class="panel"><div class="panel-head"><h2>Threat workflow</h2><span>human-gated</span></div><div class="mini-flow"><span><b>01</b>Detect</span><span><b>02</b>Correlate</span><span><b>03</b>Explain</span><span><b>04</b>Alert</span></div><p class="panel-copy">Each alert exposes its engine, confidence, contributors, trigger reasons, related evidence and safe review guidance.</p></article></div>${queue(fs)}`)}
function devsecops(){if(!state.analysis)return page("Nuclear software DevSecOps","CHANGE CONTROL · STATIC ANALYSIS · RECOVERY",empty("Analyze evidence to populate the change and configuration-control view."));const rows=state.analysis.events.filter(e=>e.event_type==="change"||e.event_type==="integrity"),fs=state.detections.filter(f=>["change","integrity"].includes(f.event.event_type)),identified=rows.filter(e=>e.event_id&&e.source).length,verified=rows.filter(e=>["valid","ok","match","true"].includes(e.integrity)).length,approved=rows.filter(e=>e.authorized&&["valid","ok","match","true"].includes(e.integrity)).length,recoverable=rows.filter(e=>String(e.baseline||"").toLowerCase()!=="n/a"&&String(e.baseline||"").trim()).length,blocked=Math.max(0,rows.length-approved),pct=(v)=>rows.length?Math.round(v/rows.length*100):0;return page("Nuclear software DevSecOps","CONTROLLED DELIVERY · EVIDENCE GATES · VALIDATED RECOVERY",`<section class="dev-banner"><div><span>REGULATED SOFTWARE ASSURANCE</span><h2>Every change needs identity, evidence, approval and a recovery path.</h2><p>The workflow below is calculated from the newest change and integrity evidence, not a static CI placeholder. NuclearShield does not deploy to plant systems.</p></div><b>HUMAN GATE</b></section><div class="metric-grid dev-metrics"><article><span>Change evidence</span><strong>${rows.length}</strong><small>change and integrity</small></article><article><span>Verified integrity</span><strong>${verified}</strong><small>valid and matching state</small></article><article><span>Approved</span><strong>${approved}</strong><small>valid and authorized</small></article><article><span>Recovery evidence</span><strong>${recoverable}</strong><small>baseline declared</small></article></div><section class="pipeline-board"><div class="panel-head"><h2>Evidence-gated delivery workflow</h2><span>${rows.length} evidence records evaluated</span></div><div class="pipeline dynamic"><div class="${identified===rows.length&&rows.length?'done':identified?'review':''}"><b>01</b><strong>Identify</strong><small>${identified}/${rows.length} attributable</small></div><i></i><div class="${verified===rows.length&&rows.length?'done':verified?'review':''}"><b>02</b><strong>Verify</strong><small>${verified}/${rows.length} integrity valid</small></div><i></i><div class="${approved===rows.length&&rows.length?'done':approved?'review':''}"><b>03</b><strong>Approve</strong><small>${approved}/${rows.length} authorized</small></div><i></i><div class="${recoverable===rows.length&&rows.length?'done':recoverable?'review':''}"><b>04</b><strong>Recover</strong><small>${recoverable}/${rows.length} baseline backed</small></div></div><div class="gate-bars"><span><b style="width:${pct(identified)}%"></b><em>identity ${pct(identified)}%</em></span><span><b style="width:${pct(verified)}%"></b><em>verification ${pct(verified)}%</em></span><span><b style="width:${pct(approved)}%"></b><em>approval ${pct(approved)}%</em></span><span><b style="width:${pct(recoverable)}%"></b><em>recovery ${pct(recoverable)}%</em></span></div></section>${alertRail(fs,"Change assurance alerts")}<div class="dev-evidence-grid"><article class="panel"><div class="panel-head"><h2>Gate exceptions</h2><span>${blocked} require review</span></div>${bar("integrity verified",verified,Math.max(1,rows.length),"teal")}${bar("human approved",approved,Math.max(1,rows.length),"amber")}${bar("baseline backed",recoverable,Math.max(1,rows.length),"purple")}</article><article class="panel"><div class="panel-head"><h2>Evidence sources</h2><span>dynamic</span></div>${[...new Set(rows.map(r=>r.source).filter(Boolean))].slice(0,6).map(s=>bar(s,rows.filter(r=>r.source===s).length,Math.max(1,rows.length),"teal")).join("")||'<div class="clear-state"><b>No change sources</b><span>No change and integrity evidence is present.</span></div>'}</article></div>${queue(fs)}`)}
function integrity(){if(!state.analysis)return page("Safety-system integrity","BASELINES · FIRMWARE · LOGIC · CONFIGURATION",empty("Analyze fresh evidence to validate safety-integrity records."));const d=domainStats(["integrity"]),valid=d.rows.filter(e=>["valid","ok","match","true"].includes(e.integrity)&&e.authorized).length,review=Math.max(0,d.rows.length-valid),pct=d.rows.length?Math.round(valid/d.rows.length*100):100;return page("Safety-system integrity","APPROVED STATE · SIGNATURE ASSURANCE · DETERMINISTIC REVIEW",`<div class="metric-grid integrity-metrics"><article><span>Integrity evidence</span><strong>${d.rows.length}</strong><small>firmware / logic / config</small></article><article><span>Approved state</span><strong>${valid}</strong><small>authorized + matching</small></article><article><span>Review state</span><strong>${review}</strong><small>mismatch / unapproved</small></article><article><span>Assurance</span><strong>${pct}%</strong><small>approved state ratio</small></article></div><div class="integrity-board"><article class="integrity-gauge"><div class="ring" style="--pct:${pct*3.6}deg"><div><b>${pct}%</b><span>baseline assurance</span></div></div><p>Evidence is compared with declared approved state; NuclearShield never writes back to a safety system.</p></article><article class="state-ledger"><div class="panel-head"><h2>Integrity state ledger</h2><span>${d.rows.length} records</span></div>${d.rows.slice(0,8).map(e=>`<div><span class="state-dot ${["valid","ok","match","true"].includes(e.integrity)&&e.authorized?'ok':'warn'}"></span><b>${esc(e.asset||e.event_id)}</b><small>${esc(e.integrity||'unknown')} · ${e.authorized?'authorized':'review authorization'}</small></div>`).join("")||'<div class="rail-clear">No integrity records observed.</div>'}</article></div>${alertRail(d.fs,"Integrity alerts")}${queue(d.fs)}`)}
