function alertRail(fs,title="Priority alerts"){
 const a=(fs||[]).filter(f=>["critical","high","medium"].includes(f.severity));
 const body=a.length?a.map(f=>`<button class="stream-alert ${esc(f.severity)}" data-event="${esc(f.event_id)}"><div class="stream-alert-top"><span class="tag ${esc(f.severity)}">${esc(f.severity)}</span><b>${esc(f.event_id)}</b><em>${Number(f.confidence)||0}% confidence</em></div><h3>${esc(f.detected)}</h3><div class="stream-alert-grid"><p><strong>How detected</strong>${esc(f.engine||"detection engine")}</p><p><strong>Source / asset</strong>${esc(f.event?.source||"evidence")} · ${esc(f.event?.asset||"unidentified")}</p><p><strong>Why triggered</strong>${esc((f.reasons||[]).join("; ")||"Configured evidence rule matched.")}</p><p><strong>Contributors</strong>${esc((f.contributors||[]).join("; ")||"Evidence context")}</p><p><strong>Related evidence</strong>${esc((f.related_events||[]).join(", ")||"none")}</p><p><strong>Safe review</strong>${esc(f.measures||"Review evidence under approved procedures.")}</p></div><span class="review-link">Review full evidence ↗</span></button>`).join(""):`<div class="stream-clear"><b>✓ No priority alert generated</b><span>The newest evidence does not meet the configured critical/high/medium threshold.</span></div>`;
 return `<section class="alert-stream"><div class="alert-stream-head"><div><span>ALERT STREAM</span><h2>${title}</h2></div><b>${a.length} active</b></div><div class="alert-stream-scroll">${body}</div></section>`;
}
function alertsOrClear(fs,title="Priority alerts"){return alertRail(fs,title)}
