function integrity(){if(!state.analysis)return page("Safety-system integrity","BASELINES · FIRMWARE · LOGIC · CONFIGURATION",empty("Analyze fresh evidence to validate safety-integrity records."));const d=domainStats(["integrity"]),valid=d.rows.filter(e=>["valid","ok","match","true"].includes(e.integrity)&&e.authorized).length,review=Math.max(0,d.rows.length-valid),pct=d.rows.length?Math.round(valid/d.rows.length*100):100;return page("Safety-system integrity","APPROVED STATE · SIGNATURE ASSURANCE · DETERMINISTIC REVIEW",`<div class="metric-grid integrity-metrics"><article><span>Integrity evidence</span><strong>${d.rows.length}</strong><small>firmware / logic / config</small></article><article><span>Approved state</span><strong>${valid}</strong><small>authorized + matching</small></article><article><span>Review state</span><strong>${review}</strong><small>mismatch / unapproved</small></article><article><span>Assurance</span><strong>${pct}%</strong><small>approved state ratio</small></article></div><div class="integrity-board"><article class="integrity-gauge"><div class="ring" style="--pct:${pct*3.6}deg"><div><b>${pct}%</b><span>baseline assurance</span></div></div><p>Evidence is compared with declared approved state; NuclearShield never writes back to a safety system.</p></article><article class="state-ledger"><div class="panel-head"><h2>Integrity state ledger</h2><span>${d.rows.length} records</span></div>${d.rows.slice(0,8).map(e=>`<div><span class="state-dot ${["valid","ok","match","true"].includes(e.integrity)&&e.authorized?'ok':'warn'}"></span><b>${esc(e.asset||e.event_id)}</b><small>${esc(e.integrity||'unknown')} · ${e.authorized?'authorized':'review authorization'}</small></div>`).join("")||'<div class="rail-clear">No integrity records observed.</div>'}</article></div>${alertRail(d.fs,"Integrity alerts")}${queue(d.fs)}`)}
function safeguards(){if(!state.analysis)return page("Nuclear material security","MC&A · PACS/IAM · RADIATION · INSIDER RISK",empty("Analyze fresh evidence to populate safeguards views."));const d=domainStats(["access","material","radiation"]),corr=d.fs.filter(f=>f.related_events?.length),mix=["access","material","radiation"].map(k=>[k,d.rows.filter(e=>e.event_type===k).length]);return page("Nuclear material security & safeguards","PHYSICAL-CYBER CONVERGENCE · CHAIN OF CUSTODY",`<div class="metric-grid accent-metrics">${mix.map(x=>`<article><span>${x[0]} evidence</span><strong>${x[1]}</strong><small>newest analysis</small></article>`).join("")}<article><span>Correlated risks</span><strong>${corr.length}</strong><small>actor/asset relationships</small></article></div><div class="viz-grid">${donut("Safeguards evidence mix",mix)}${spark("Material / radiation observations",values(d.rows.filter(e=>["material","radiation"].includes(e.event_type))),"evidence sequence")}</div>${alertRail(d.fs,"Safeguards alerts")}<div class="dashboard-grid"><article class="panel"><h2>Correlation coverage</h2>${bar("linked findings",corr.length,Math.max(1,d.fs.length),"red")}${bar("all safeguards findings",d.fs.length,Math.max(1,d.rows.length),"amber")}</article><article class="panel"><h2>Why correlation matters</h2><ol class="steps"><li>PACS/IAM establishes attributable access context.</li><li>MC&amp;A represents material-accounting evidence.</li><li>Radiation evidence adds movement/context signals.</li><li>Shared actor or asset identifiers expose combinations requiring safeguards review.</li></ol></article></div>${queue(d.fs)}`)}
function ai(){if(!state.analysis)return page("AI-driven nuclear threat detection","ANOMALIES · CORRELATION · THREAT ALERTS",empty("Analyze evidence to activate threat detection."));const fs=state.detections,su=state.analysis.summary||{},types=["network","integrity","access","material","radiation","change"],correlated=fs.filter(f=>f.related_events?.length),aiFindings=fs.filter(f=>String(f.engine).includes("robust")||String(f.engine).includes("correlation")),sev=["critical","high","medium","low"].map(k=>[k,fs.filter(f=>f.severity===k).length]);return page("AI-driven threat detection","DETECT · CORRELATE · EXPLAIN · ALERT · AUTHORIZE",`<div class="notice"><b>Safety boundary:</b> Threat detection prioritizes uploaded evidence and generates review alerts. It cannot execute containment or modify a plant system.</div><div class="metric-grid accent-metrics"><article><span>Total findings</span><strong>${fs.length}</strong><small>across evidence domains</small></article><article><span>AI / correlation</span><strong>${aiFindings.length}</strong><small>robust + correlation engines</small></article><article><span>Cross-domain links</span><strong>${correlated.length}</strong><small>related actor/asset evidence</small></article><article><span>Critical / high</span><strong>${fs.filter(f=>["critical","high"].includes(f.severity)).length}</strong><small>priority human review</small></article></div><div class="viz-grid">${donut("Threat severity",sev)}${donut("Threats by domain",types.map(t=>[t,fs.filter(f=>f.event.event_type===t).length]))}</div>${alertRail(fs,"Generated threat alerts")}<div class="dashboard-grid"><article class="panel"><div class="panel-head"><h2>Detection engine activity</h2><span>${Object.keys(su.engines||{}).length} engines</span></div>${Object.entries(su.engines||{}).map(([k,v])=>bar(k,v,Math.max(1,fs.length))).join("")||'<div class="clear-state"><b>No engine findings</b><span>No detection engine produced a finding in this run.</span></div>'}</article><article class="panel"><div class="panel-head"><h2>Threat workflow</h2><span>human-gated</span></div><div class="mini-flow"><span><b>01</b>Detect</span><span><b>02</b>Correlate</span><span><b>03</b>Explain</span><span><b>04</b>Alert</span></div><p class="panel-copy">Each alert exposes its engine, confidence, contributors, trigger reasons, related evidence and safe review guidance.</p></article></div>${queue(fs)}`)}
function devsecops(){if(!state.analysis)return page("Nuclear software DevSecOps","CHANGE CONTROL · STATIC ANALYSIS · RECOVERY",empty("Analyze evidence to populate the change and configuration-control view."));const rows=state.analysis.events.filter(e=>e.event_type==="change"||e.event_type==="integrity"),fs=state.detections.filter(f=>["change","integrity"].includes(f.event.event_type)),identified=rows.filter(e=>e.event_id&&e.source).length,verified=rows.filter(e=>["valid","ok","match","true"].includes(e.integrity)).length,approved=rows.filter(e=>e.authorized&&["valid","ok","match","true"].includes(e.integrity)).length,recoverable=rows.filter(e=>String(e.baseline||"").toLowerCase()!=="n/a"&&String(e.baseline||"").trim()).length,blocked=Math.max(0,rows.length-approved),pct=(v)=>rows.length?Math.round(v/rows.length*100):0;return page("Nuclear software DevSecOps","CONTROLLED DELIVERY · EVIDENCE GATES · VALIDATED RECOVERY",`<section class="dev-banner"><div><span>REGULATED SOFTWARE ASSURANCE</span><h2>Every change needs identity, evidence, approval and a recovery path.</h2><p>The workflow below is calculated from the newest change and integrity evidence, not a static CI placeholder. NuclearShield does not deploy to plant systems.</p></div><b>HUMAN GATE</b></section><div class="metric-grid dev-metrics"><article><span>Change evidence</span><strong>${rows.length}</strong><small>change and integrity</small></article><article><span>Verified integrity</span><strong>${verified}</strong><small>valid and matching state</small></article><article><span>Approved</span><strong>${approved}</strong><small>valid and authorized</small></article><article><span>Recovery evidence</span><strong>${recoverable}</strong><small>baseline declared</small></article></div><section class="pipeline-board"><div class="panel-head"><h2>Evidence-gated delivery workflow</h2><span>${rows.length} evidence records evaluated</span></div><div class="pipeline dynamic"><div class="${identified===rows.length&&rows.length?'done':identified?'review':''}"><b>01</b><strong>Identify</strong><small>${identified}/${rows.length} attributable</small></div><i></i><div class="${verified===rows.length&&rows.length?'done':verified?'review':''}"><b>02</b><strong>Verify</strong><small>${verified}/${rows.length} integrity valid</small></div><i></i><div class="${approved===rows.length&&rows.length?'done':approved?'review':''}"><b>03</b><strong>Approve</strong><small>${approved}/${rows.length} authorized</small></div><i></i><div class="${recoverable===rows.length&&rows.length?'done':recoverable?'review':''}"><b>04</b><strong>Recover</strong><small>${recoverable}/${rows.length} baseline backed</small></div></div><div class="gate-bars"><span><b style="width:${pct(identified)}%"></b><em>identity ${pct(identified)}%</em></span><span><b style="width:${pct(verified)}%"></b><em>verification ${pct(verified)}%</em></span><span><b style="width:${pct(approved)}%"></b><em>approval ${pct(approved)}%</em></span><span><b style="width:${pct(recoverable)}%"></b><em>recovery ${pct(recoverable)}%</em></span></div></section>${alertRail(fs,"Change assurance alerts")}<div class="dev-evidence-grid"><article class="panel"><div class="panel-head"><h2>Gate exceptions</h2><span>${blocked} require review</span></div>${bar("integrity verified",verified,Math.max(1,rows.length),"teal")}${bar("human approved",approved,Math.max(1,rows.length),"amber")}${bar("baseline backed",recoverable,Math.max(1,rows.length),"purple")}</article><article class="panel"><div class="panel-head"><h2>Evidence sources</h2><span>dynamic</span></div>${[...new Set(rows.map(r=>r.source).filter(Boolean))].slice(0,6).map(s=>bar(s,rows.filter(r=>r.source===s).length,Math.max(1,rows.length),"teal")).join("")||'<div class="clear-state"><b>No change sources</b><span>No change and integrity evidence is present.</span></div>'}</article></div>${queue(fs)}`)}
async function compliance(){if(!state.analysis)return page("Compliance evidence","IEC 62645 · NRC RG 5.71 · IAEA GUIDANCE",empty("Analyze evidence to build the demonstration compliance mapping."));const s=state.analysis.summary||{},types=s.evidence_types||{},controls=[["SCADA & network defense","IEC 62645","NRC RG 5.71","IAEA computer security",types.network||0,"Passive network evidence, segmentation and anomaly review"],["Safety-system integrity","IEC 62645 lifecycle","NRC defensive architecture","IAEA safety/security interface",types.integrity||0,"Approved-state, signature and authorization evidence"],["Material safeguards","Security programme controls","Access-control evidence","IAEA safeguards / nuclear security",(types.material||0)+(types.radiation||0)+(types.access||0),"PACS, MC&A, radiation and actor correlation"],["Secure change control","Lifecycle assurance","Configuration management","IAEA configuration governance",types.change||0,"Attributable change, validation, approval and recovery evidence"],["Audit & reporting","Evidence retention","Assessment records","IAEA assurance evidence",state.analysis.event_count||0,"SHA-256 provenance, findings, HTML report and audit history"]],covered=controls.filter(c=>c[4]>0).length,pct=Math.round(covered/controls.length*100);return page("Compliance evidence","TRACEABLE MAPPING · DEMONSTRATION ONLY · NOT CERTIFICATION",`<div class="notice"><b>Scope:</b> This workspace maps uploaded evidence to learning oriented control themes. It does not claim regulatory certification or formal compliance.</div><div class="metric-grid compliance-metrics"><article><span>Control domains</span><strong>${controls.length}</strong><small>demonstration mappings</small></article><article><span>Evidence-backed</span><strong>${covered}</strong><small>domains with uploaded evidence</small></article><article><span>Mapping coverage</span><strong>${pct}%</strong><small>evidence presence only</small></article><article><span>Audit findings</span><strong>${state.analysis.finding_count}</strong><small>traceable review items</small></article></div><div class="compliance-progress"><div><b style="width:${pct}%"></b></div><span>${pct}% of demonstration control domains have supporting evidence in this run</span></div><div class="table-wrap panel compliance-table"><table><thead><tr><th>Control domain</th><th>IEC 62645 theme</th><th>NRC RG 5.71 theme</th><th>IAEA theme</th><th>Evidence</th><th>Demonstration support</th></tr></thead><tbody>${controls.map(c=>`<tr><td><b>${c[0]}</b></td><td>${c[1]}</td><td>${c[2]}</td><td>${c[3]}</td><td><span class="coverage-pill ${c[4]?'yes':'no'}">${c[4]} records</span></td><td>${c[5]}</td></tr>`).join("")}</tbody></table></div><div class="dashboard-grid"><article class="panel"><h2>Evidence traceability</h2><p>Analysis <b>#${state.analysis.id}</b> · ${esc(state.analysis.filename)}</p><code>${esc(state.analysis.digest)}</code><p>${state.analysis.event_count} accepted records · ${state.analysis.finding_count} findings.</p></article><article class="panel"><h2>Assurance boundary</h2><p>Framework mappings are design and examination evidence. Regulatory acceptance requires the applicable authority, facility programme, formal assessment and qualified personnel.</p><a class="button small" target="_blank" href="/api/report?analysis_id=${state.analysis.id}">Open evidence report ↗</a></article></div>`)}
async function monitoring(){const [st,m,n]=await Promise.all([api("/api/platform-status"),api("/api/monitoring-summary"),api("/api/network-monitoring")]),l=m.latest||{},u=st.public_urls||{application:location.origin,prometheus:"http://localhost:9090",grafana:"http://localhost:3000"},z=n.zeek||{records:[],findings:[],protocols:{},conversations:{}},su=n.suricata||{records:[],findings:[],signatures:{},categories:{}},health=n.sensor_health||{},queries=[["Request rate","rate(nuclearshield_http_requests_total[5m])"],["Finding rate","nuclearshield_latest_findings"],["Processing coverage","nuclearshield_latest_processing_coverage_percent"],["Accepted evidence","nuclearshield_latest_accepted_records"],["Critical findings",'nuclearshield_latest_findings_by_severity{severity="critical"}']];const feed=(rows,kind)=>rows.length?rows.slice(0,12).map(r=>`<button class="sensor-row" data-event="${esc(r.event_id)}"><span>${esc(r.timestamp||', ')}</span><strong>${esc(r.asset||'unidentified asset')}</strong><small>${esc(r.source||kind)} · ${esc(r.protocol||'unknown')} · ${esc(r.src_ip||', ')}:${esc(r.src_port||', ')} → ${esc(r.dst_ip||', ')}:${esc(r.dst_port||', ')}</small>${r.signature?`<small class="signature">${esc(r.signature)}</small>`:''}${r.finding?'<em>finding linked · open evidence ↗</em>':'<em class="ok">parsed and observed</em>'}</button>`).join(""):`<div class="sensor-zero"><b>0 records classified</b><span>No ${kind}-format records were detected in the newest uploaded evidence.</span></div>`;return page("Platform monitoring","ZEEK · SURICATA · PROMETHEUS · GRAFANA · QUERY CONSOLE",`<div class="monitor-hero"><div><span>OBSERVABILITY</span><h2>Passive sensor parsing, evidence correlation and live platform telemetry.</h2></div><div class="live-badge">● LIVE STACK</div></div><div class="metric-grid monitor-metrics"><article><span>Zeek parsed</span><strong>${z.records.length}</strong><small>${Object.keys(z.protocols||{}).length} protocols · ${z.findings.length} findings</small></article><article><span>Suricata parsed</span><strong>${su.records.length}</strong><small>${Object.keys(su.signatures||{}).length} signatures · ${su.findings.length} findings</small></article><article><span>Sensor classification</span><strong>${health.classification_percent||0}%</strong><small>${health.classified||0}/${health.total_network||0} network records</small></article><article><span>Processing coverage</span><strong>${l.coverage||0}%</strong><small>latest analysis pipeline</small></article></div><div class="sensor-analytics"><article class="panel"><div class="panel-head"><h2>Zeek protocol analysis</h2><span>parsed from current evidence</span></div>${Object.entries(z.protocols||{}).slice(0,6).map(([k,v])=>bar(k,v,Math.max(1,z.records.length),"teal")).join("")||'<div class="sensor-zero"><b>No Zeek protocols</b><span>Upload a Zeek conn.log or compatible evidence to populate this analysis.</span></div>'}</article><article class="panel"><div class="panel-head"><h2>Suricata signature analysis</h2><span>parsed from current evidence</span></div>${Object.entries(su.signatures||{}).slice(0,6).map(([k,v])=>bar(k,v,Math.max(1,su.records.length),"red")).join("")||'<div class="sensor-zero"><b>No Suricata signatures</b><span>Upload EVE JSON/JSONL alert evidence to populate this analysis.</span></div>'}</article></div><div class="sensor-grid"><article class="sensor-console zeek"><div class="sensor-head"><div><span>ZEEK ENGINE</span><h2>Parsed passive metadata</h2></div><b>${z.records.length} records</b></div><div class="sensor-list">${feed(z.records,"Zeek")}</div></article><article class="sensor-console suricata"><div class="sensor-head"><div><span>SURICATA ENGINE</span><h2>Parsed IDS alert evidence</h2></div><b>${su.records.length} records</b></div><div class="sensor-list">${feed(su.records,"Suricata")}</div></article></div><section class="observability-launch"><a href="${u.prometheus}" target="_blank"><span>PROMETHEUS</span><h3>Open Prometheus</h3><p>Explore metrics, targets, graph queries and runtime series.</p><b>Launch ↗</b></a><a href="${u.prometheus}/targets" target="_blank"><span>TARGETS</span><h3>Scrape health</h3><p>Verify NuclearShield target state and scrape status.</p><b>Open targets ↗</b></a><a href="${u.grafana}/d/nuclearshield/nuclearshield-evidence-assurance?orgId=1&refresh=5s" target="_blank"><span>GRAFANA</span><h3>Telemetry dashboard</h3><p>Open the provisioned NuclearShield dashboard.</p><b>Launch ↗</b></a><a href="${u.application}/metrics" target="_blank"><span>METRICS</span><h3>Raw exposition</h3><p>Inspect the application's Prometheus-format metrics.</p><b>View metrics ↗</b></a></section><section class="query-console"><div class="panel-head"><h2>Prometheus query shortcuts</h2><span>open directly in Prometheus</span></div><div>${queries.map(([name,expr])=>`<a href="${q(expr,u.prometheus)}" target="_blank"><span>${name}</span><code>${esc(expr)}</code><b>Run ↗</b></a>`).join("")}</div></section><div class="status-strip">${Object.entries(st).filter(([k])=>k!=="public_urls").map(([k,v])=>`<span><i class="${["healthy","ready","none","true"].includes(String(v))?'':'down'}"></i><b>${esc(k.replaceAll('_',' '))}</b>${esc(String(v))}</span>`).join("")}</div><div class="notice"><b>Dynamic endpoints:</b> App ${esc(u.application)} · Prometheus ${esc(u.prometheus)} · Grafana ${esc(u.grafana)} · Grafana login: admin / nuclearshield-demo.</div>`) }

async function audit(){const [rows,s]=await Promise.all([api("/api/audit?limit=500"),api("/api/audit-summary")]),actions=Object.entries(s.actions||{}).sort((a,b)=>b[1]-a[1]);return page("Audit trail","ATTRIBUTABLE · HASH-LINKED · SEARCHABLE · REVIEWABLE",`<div class="metric-grid audit-metrics"><article><span>Audit entries</span><strong>${s.entries}</strong><small>persistent records</small></article><article><span>Actors</span><strong>${s.actors}</strong><small>attributable identities</small></article><article><span>Action classes</span><strong>${actions.length}</strong><small>recorded workflows</small></article><article><span>Latest record</span><strong>${s.latest_timestamp?"RECENT":"NONE"}</strong><small>${esc(s.latest_timestamp||"No entries")}</small></article></div><div class="audit-overview"><article class="panel"><div class="panel-head"><h2>Action distribution</h2><span>${s.entries} entries</span></div>${actions.slice(0,8).map(([k,v])=>bar(k.replaceAll('_',' '),v,Math.max(1,s.entries),"teal")).join("")||'<div class="clear-state"><b>No audit actions</b><span>Audit actions appear after evidence operations.</span></div>'}</article><article class="panel audit-integrity"><div class="panel-head"><h2>Audit assurance</h2><span>application boundary</span></div><div class="audit-check"><b>SHA-256 linked</b><span>Each operation retains its evidence digest reference.</span></div><div class="audit-check"><b>Attributable actor</b><span>${s.actors} actor identity set recorded.</span></div><div class="audit-check"><b>Persistent history</b><span>Analysis deletion keeps its audit action.</span></div><div class="audit-check caution"><b>Demonstration limitation</b><span>SQLite is not an external WORM or SIEM audit store.</span></div></article></div><div class="filterbar audit-tools"><input id="auditSearch" placeholder="Search filename, digest, actor or action"><select id="auditAction"><option value="">All actions</option>${actions.map(([k])=>`<option value="${esc(k)}">${esc(k.replaceAll('_',' '))}</option>`).join("")}</select><a class="button ghost" href="/api/audit?limit=500" target="_blank">Open audit JSON ↗</a><span id="auditCount">${rows.length} entries</span></div><div id="auditTable" class="table-wrap panel">${auditTable(rows)}</div><div class="notice"><b>Audit boundary:</b> ${esc(s.chain_note)}. Audit data supports exam traceability and incident review; it does not claim immutable regulatory retention.</div>`) }
function auditTable(rows){return `<table><thead><tr><th>UTC time</th><th>Action / actor</th><th>Evidence SHA-256</th><th>Analysis details</th></tr></thead><tbody>${rows.map(a=>{const linked=state.analyses.find(x=>x.digest===a.evidence_digest);return `<tr><td>${esc(new Date(a.timestamp).toISOString().replace('T', ' '))}</td><td><b>${esc(a.action)}</b><small>${esc(a.actor)}</small></td><td><code>${esc(a.evidence_digest)}</code></td><td>${Object.entries(a.details).map(([k,v])=>`<span class="audit-chip"><b>${esc(k)}</b> ${esc(String(v))}</span>`).join("")}${linked?`<button class="audit-delete" data-delete-analysis="${esc(linked.id)}" data-filename="${esc(linked.filename)}">Delete analyzed file</button>`:""}</td></tr>`}).join("")||'<tr><td colspan="4">No audit entries match this search.</td></tr>'}</tbody></table>`}
function showDetail(id){const f=state.detections.find(x=>x.event_id===id);if(!f)return;const d=document.createElement("dialog");d.innerHTML=`<button class="close">×</button><span class="tag ${f.severity}">${f.severity} · score ${f.score}</span><h2>${esc(f.detected)}</h2><dl><div><dt>Event / source</dt><dd>${esc(f.event_id)} · ${esc(f.event.source)}</dd></div><div><dt>Engine / confidence</dt><dd>${esc(f.engine)} · ${f.confidence}%</dd></div><div><dt>Why it triggered</dt><dd>${esc(f.reasons.join("; "))}</dd></div><div><dt>Contributors</dt><dd>${esc(f.contributors.join("; "))}</dd></div><div><dt>Related events</dt><dd>${esc(f.related_events.join(", ")||"none")}</dd></div><div><dt>Recommended measures</dt><dd>${esc(f.measures)}</dd></div></dl><div class="authorization">Human and safety authorization required. NuclearShield is read only.</div>`;document.body.append(d);d.showModal();d.querySelector(".close").onclick=()=>{d.close();d.remove()}}
function bind(){const pick=document.querySelector("#datasetSelect");if(pick)pick.onchange=async()=>{await load(pick.value);render(false)};document.querySelectorAll("[data-event]").forEach(b=>b.onclick=()=>showDetail(b.dataset.event));document.querySelectorAll("[data-delete-analysis]").forEach(b=>b.onclick=()=>removeAnalysis(b.dataset.deleteAnalysis,b.dataset.filename));const form=document.querySelector("#uploadForm"),input=document.querySelector("#evidence"),demo=document.querySelector("#demo"),drop=document.querySelector("#dropzone");if(input)input.onchange=()=>document.querySelector("#fileName").textContent=input.files[0]?.name||"No file selected";if(drop){["dragenter","dragover"].forEach(n=>drop.addEventListener(n,e=>{e.preventDefault();drop.classList.add("drag")}));["dragleave","drop"].forEach(n=>drop.addEventListener(n,e=>{e.preventDefault();drop.classList.remove("drag")}));drop.addEventListener("drop",e=>{if(e.dataTransfer.files[0]){const dt=new DataTransfer();dt.items.add(e.dataTransfer.files[0]);input.files=dt.files;input.onchange()}})}if(form)form.onsubmit=e=>{e.preventDefault();if(input.files[0])submit(input.files[0])};if(demo)demo.onclick=async()=>{const r=await fetch("/sample-data/synthetic-evidence.csv");submit(new File([await r.blob()],"synthetic-evidence.csv",{type:"text/csv"}))};["typeFilter","severityFilter","search"].forEach(id=>{const n=document.querySelector("#"+id);if(n)n.oninput=filter})}
async function removeAnalysis(id,filename){if(!confirm(`Delete the report and stored analysis for ${filename}? The audit record will be retained.`))return;try{await api("/api/analyses/"+id,{method:"DELETE"});state.analysis=null;await load();notify("Report and analysis deleted");render(false)}catch(e){notify(e.message,"error")}}
async function submit(file){const status=document.querySelector("#uploadStatus"),body=new FormData();body.append("file",file);status.textContent="Normalizing and running five analysis engines…";try{const d=await api("/api/ingest",{method:"POST",body});status.textContent=`Complete: ${d.events} accepted, ${d.rejected.length} rejected, ${d.findings.length} findings, ${d.summary.processing_coverage}% coverage.`;notify("Complete evidence analysis finished");state.analysis=null;setTimeout(()=>location.hash="#/dashboard",600)}catch(e){status.textContent=e.message;notify(e.message,"error")}}
function filter(){const t=document.querySelector("#typeFilter")?.value||"",s=document.querySelector("#severityFilter")?.value||"",q=(document.querySelector("#search")?.value||"").toLowerCase();const list=state.detections.filter(f=>(!t||f.event.event_type===t)&&(!s||f.severity===s)&&(!q||JSON.stringify(f).toLowerCase().includes(q)));document.querySelector("#queue").innerHTML=queue(list);document.querySelectorAll("[data-event]").forEach(b=>b.onclick=()=>showDetail(b.dataset.event))}
async function render(reload=true){document.querySelectorAll("#topnav a").forEach(a=>a.classList.toggle("active",a.dataset.route===route()));app.innerHTML='<div class="loading">Loading dynamic evidence platform…</div>';try{if(reload)await load();const r=route(),views={home:landing,upload,dashboard,detections,evidence,scada,ai,devsecops,integrity,safeguards,reports,monitoring,audit};app.innerHTML=r==="compliance"?await compliance():await (views[r]||landing)();bind()}catch(e){app.innerHTML=`<div class="fatal"><h2>Platform unavailable</h2><p>${esc(e.message)}</p><button class="button" onclick="location.reload()">Retry</button></div>`}}
async function refreshAudit(){const search=document.querySelector("#auditSearch")?.value||"",action=document.querySelector("#auditAction")?.value||"";let url="/api/audit?limit=500";if(search)url+="&search="+encodeURIComponent(search);if(action)url+="&action="+encodeURIComponent(action);const rows=await api(url);const table=document.querySelector("#auditTable"),count=document.querySelector("#auditCount");if(table){table.innerHTML=auditTable(rows);table.querySelectorAll("[data-delete-analysis]").forEach(b=>b.onclick=()=>removeAnalysis(b.dataset.deleteAnalysis,b.dataset.filename))}if(count)count.textContent=rows.length+" entries"}
document.addEventListener("input",e=>{if(e.target.id==="auditSearch")refreshAudit()});
document.addEventListener("change",e=>{if(e.target.id==="auditAction")refreshAudit()});
window.addEventListener("hashchange",()=>render());document.querySelector("#menu").onclick=()=>document.querySelector("#topnav").classList.toggle("open");render();
